/// The main structure for selecting plural rules.
///
/// # Examples
///
/// ```
/// use intl_pluralrules::{PluralRules, PluralRuleType, PluralCategory};
/// use unic_langid::LanguageIdentifier;
///
/// let langid: LanguageIdentifier = "naq".parse().expect("Parsing failed.");
/// let pr_naq = PluralRules::create(langid, PluralRuleType::CARDINAL).unwrap();
/// assert_eq!(pr_naq.select(1), Ok(PluralCategory::ONE));
/// assert_eq!(pr_naq.select("2"), Ok(PluralCategory::TWO));
/// assert_eq!(pr_naq.select(5.0), Ok(PluralCategory::OTHER));
/// ```
// #[derive(Clone)]
export class PluralRules {
  locale: LanguageIdentifier;
  function: PluralRule;

  constructor(locale: LanguageIdentifier, function_: PluralRule) {
    this.locale = locale;
    this.function = function_;
  }

  /// Returns an instance of PluralRules.
  ///
  /// # Examples
  /// ```
  /// use intl_pluralrules::{PluralRules, PluralRuleType, PluralCategory};
  /// use unic_langid::LanguageIdentifier;
  ///
  /// let langid: LanguageIdentifier = "naq".parse().expect("Parsing failed.");
  /// let pr_naq = PluralRules::create(langid, PluralRuleType::CARDINAL);
  /// assert_eq!(pr_naq.is_ok(), !pr_naq.is_err());
  ///
  /// let langid: LanguageIdentifier = "xx".parse().expect("Parsing failed.");
  /// let pr_broken = PluralRules::create(langid, PluralRuleType::CARDINAL);
  /// assert_eq!(pr_broken.is_err(), !pr_broken.is_ok());
  /// ```
  // crate: intl_pluralrules-7.0.2/src/lib.rs:101 create
  static create(langid: LanguageIdentifier, prt: PluralRuleType): Result<PluralRules, string> {
    // PORT: `L: Into<LanguageIdentifier>`: only the identity conversion is used.
    let returned_rule: Result<PluralRule, number>;
    switch (prt) {
      case "CARDINAL": {
        const idx = binary_search_by(rules.PRS_CARDINAL, ([l]) => l.cmp(langid));
        returned_rule = idx.$ === "Ok" ? Ok(rules.PRS_CARDINAL[idx._0]![1]) : idx;
        break;
      }
      case "ORDINAL": {
        const idx = binary_search_by(rules.PRS_ORDINAL, ([l]) => l.cmp(langid));
        returned_rule = idx.$ === "Ok" ? Ok(rules.PRS_ORDINAL[idx._0]![1]) : idx;
        break;
      }
    }
    switch (returned_rule.$) {
      case "Ok":
        return Ok(new PluralRules(langid, returned_rule._0));
      case "Err":
        return Err("unknown locale");
    }
  }

  /// Returns a result of the plural category for the given input.
  ///
  /// If the input is not numeric.
  ///
  /// # Examples
  /// ```
  /// use intl_pluralrules::{PluralRules, PluralRuleType, PluralCategory};
  /// use unic_langid::LanguageIdentifier;
  ///
  /// let langid: LanguageIdentifier = "naq".parse().expect("Parsing failed.");
  /// let pr_naq = PluralRules::create(langid, PluralRuleType::CARDINAL).unwrap();
  /// assert_eq!(pr_naq.select(1), Ok(PluralCategory::ONE));
  /// assert_eq!(pr_naq.select(2), Ok(PluralCategory::TWO));
  /// assert_eq!(pr_naq.select(5), Ok(PluralCategory::OTHER));
  /// ```
  // crate: intl_pluralrules-7.0.2/src/lib.rs:140 select
  select<N>(number: N, try_into: (n: N) => Result<PluralOperands, unknown>): Result<PluralCategory, string> {
    // PORT: `N: TryInto<PluralOperands>`: the conversion is passed in (`try_into`), e.g.
    // `PluralOperands.try_from_signed` for an i32, `(s) => PluralOperands.try_from_str(s)` for a
    // `&str`, `(x) => PluralOperands.try_from_convert(x, display_f64)` for an f64, or
    // `(x) => Ok(PluralOperands.from_unsigned(x))` for a usize.
    const ops = try_into(number);
    const pr = this.function;
    switch (ops.$) {
      case "Ok":
        return Ok(pr(ops._0));
      case "Err":
        return Err("Argument can not be parsed to operands.");
    }
  }

  /// Returns a list of the available locales.
  ///
  /// # Examples
  /// ```
  /// use intl_pluralrules::{PluralRules, PluralRuleType};
  ///
  /// assert_eq!(
  ///     PluralRules::get_locales(PluralRuleType::CARDINAL).is_empty(),
  ///     false
  /// );
  /// ```
  // crate: intl_pluralrules-7.0.2/src/lib.rs:163 get_locales
  static get_locales(prt: PluralRuleType): LanguageIdentifier[] {
    let prs: readonly (readonly [LanguageIdentifier, PluralRule])[];
    switch (prt) {
      case "CARDINAL":
        prs = rules.PRS_CARDINAL;
        break;
      case "ORDINAL":
        prs = rules.PRS_ORDINAL;
        break;
    }
    return prs.map(([l]) => l.clone());
  }

  /// Returns the locale name for this PluralRule instance.
  ///
  /// # Examples
  /// ```
  /// use intl_pluralrules::{PluralRules, PluralRuleType};
  /// use unic_langid::LanguageIdentifier;
  ///
  /// let langid: LanguageIdentifier = "naq".parse().expect("Parsing failed.");
  /// let pr_naq = PluralRules::create(langid.clone(), PluralRuleType::CARDINAL).unwrap();
  /// assert_eq!(pr_naq.get_locale(), &langid);
  /// ```
  // crate: intl_pluralrules-7.0.2/src/lib.rs:182 get_locale
  get_locale(): LanguageIdentifier {
    return this.locale;
  }

  /** `#[derive(Clone)]` */
  clone(): PluralRules {
    return new PluralRules(this.locale.clone(), this.function);
  }
}

// PORT: `<[T]>::binary_search_by_key(&b, f)` = `binary_search_by(|k| f(k).cmp(b))`; this is
// `core::slice::binary_search_by` (library/core/src/slice/mod.rs:2982 at the pin), the same probe
// sequence, so for a table that were not sorted the same entry would (not) be found. (A shared
// src/std slice module would own this; see handoff.)
function binary_search_by<T>(v: readonly T[], f: (x: T) => -1 | 0 | 1): Result<number, number> {
  let size = v.length;
  if (size === 0) {
    return Err(0);
  }
  let base = 0;

  // This loop intentionally doesn't have an early exit if the comparison
  // returns Equal. We want the number of loop iterations to depend *only*
  // on the size of the input slice so that the CPU can reliably predict
  // the loop count.
  while (size > 1) {
    const half = Math.floor(size / 2);
    const mid = base + half;

    const cmp = f(v[mid]!);

    base = cmp === 1 ? base : mid;

    size -= half;
  }

  const cmp = f(v[base]!);
  if (cmp === 0) {
    return Ok(base);
  } else {
    const result = base + (cmp === -1 ? 1 : 0);
    return Err(result);
  }
}
